import { createContext, useCallback, useState } from 'react';

import { menuEvents } from '@common/utils/menu-window-provider';

export type SearchViewExpansionState = {
    method?: 'click' | 'keystroke';
    shouldExpand: boolean;
};

type WindowSearchMenuContextType = {
    shouldExpandMenu: SearchViewExpansionState;
    setShouldExpandMenu: (shouldExpandMenu: SearchViewExpansionState) => void;
};

export const WindowSearchMenuContext = createContext<WindowSearchMenuContextType>({
    shouldExpandMenu: { shouldExpand: false },
    setShouldExpandMenu: () => {
        return;
    }
});

export const WindowSearchMenuContextProvider = ({ children }: { children?: React.ReactNode }) => {
    const [shouldExpandMenu, setShouldExpandMenu] = useState<SearchViewExpansionState>({ shouldExpand: false });

    const setShouldExpandMenuCallback = useCallback((newShouldExpandMenu: SearchViewExpansionState) => {
        if (!newShouldExpandMenu.shouldExpand) {
            // emit event that the search menu is closing
            menuEvents.emit('search-menu-closed', fin.me.identity.name);
        }
        setShouldExpandMenu(newShouldExpandMenu);
    }, []);

    return (
        <WindowSearchMenuContext.Provider
            value={{ shouldExpandMenu, setShouldExpandMenu: setShouldExpandMenuCallback }}
        >
            {children}
        </WindowSearchMenuContext.Provider>
    );
};
