import { useEffect, useLayoutEffect, useRef } from 'react';

import { createLogger } from '../utils/logger';

type AsyncCleanup = () => Promise<unknown> | void;
type Subscriber<T> = (cb: T) => Promise<AsyncCleanup> | AsyncCleanup;
type SymmetricSubscriber<T> = (cb: T) => Promise<unknown> | void;

const logger = createLogger('useAsyncSubscription');

// Avoid SSR issues by using useEffect on server
const useIsomorphicLayoutEffect = typeof window !== 'undefined' ? useLayoutEffect : useEffect;

/**
 * React hook to manage async subscription lifecycles.
 *
 * What This Solves:
 * Naive subscription patterns in React effects can cause performance issues.
 * Every render causes unsubscribe + resubscribe when dependencies change,
 * leading to expensive async calls, brief unsubscribed moments where events
 * are missed, API churn, and race conditions.
 *
 * This hook solves these issues by:
 * - Using a ref to update the callback without re-subscribing
 * - Handling async subscribe/unsubscribe operations safely
 * - Preventing subscription activation if component unmounts during async subscribe
 * - Ensuring cleanup happens on unmount
 *
 * Usage Notes:
 * Only use useAsyncSubscription directly if you need a dynamic subscriber
 * or are dealing with an API that returns a unique subscription ID/Token.
 * * For standard add/remove listener APIs, prefer createAsyncSubscription.
 *
 * @example
 * // Subscriber must return a cleanup function
 * const subscribe = useCallback(async (cb) => {
 * const subId = await api.subscribe(cb);
 * return () => api.unsubscribe(subId);
 * }, []);
 * * useAsyncSubscription('myApi', subscribe, handleData);
 *
 * @param logIdentifier - Logging identifier.
 * @param subscriber - Stable async function that sets up the listener and returns a cleanup function.
 * @param callback - The handler from your component.
 */
export function useAsyncSubscription<T extends (...args: any[]) => void>(
    logIdentifier: string,
    subscriber: Subscriber<T>,
    callback: T
) {
    // 1. STABILIZE THE CALLBACK (latestref pattern)
    const callbackRef = useRef<T | null>(callback);

    // Use useLayoutEffect to ensure ref is updated before any paints/events
    useIsomorphicLayoutEffect(() => {
        callbackRef.current = callback;
    });

    // Safety Cleanup: clear ref on unmount
    useEffect(
        () => () => {
            callbackRef.current = null;
        },
        []
    );

    // 2. MANAGE THE ASYNC LIFECYCLE
    useEffect(() => {
        let isMounted = true;
        let cleanupFn: AsyncCleanup | undefined;

        // Wrapper to call the *latest* callback safely
        const dynamicHandler = ((...args: Parameters<T>) => {
            if (callbackRef.current) {
                try {
                    callbackRef.current(...args);
                } catch (error) {
                    logger.error('dynamicHandler', `[${logIdentifier}] Error in callback`, { error, args });
                }
            } else {
                // Downgraded to debug as this is expected during unmount
                logger.debug(
                    'dynamicHandler',
                    `[${logIdentifier}] Callback ref is null, ignoring event received during cleanup`,
                    { args }
                );
            }
        }) as T;

        const connect = async () => {
            try {
                // 1. Subscribe and get cleanup function
                const result = await subscriber(dynamicHandler);

                // 2. SAFETY CHECK: Did we unmount while waiting?
                if (!isMounted) {
                    logger.warn('connect', `[${logIdentifier}] Unmounted during subscribe, rolling back`);
                    if (result) await result();
                    return;
                }

                // 3. Success
                cleanupFn = result;
                logger.debug('connect', `[${logIdentifier}] Subscribed successfully`);
            } catch (error) {
                logger.error('connect', `[${logIdentifier}] Failed to subscribe`, { error });
            }
        };

        connect();

        // 3. CLEANUP
        return () => {
            isMounted = false;
            if (cleanupFn) {
                logger.debug('cleanup', `[${logIdentifier}] Unsubscribing`);
                Promise.resolve(cleanupFn()).catch((error) => {
                    logger.error('cleanup', `[${logIdentifier}] Failed to unsubscribe`, { error });
                });
            }
        };
    }, [subscriber, logIdentifier]);
}

/**
 * Factory to create a custom hook with predefined subscriber/unsubscriber functions.
 *
 * This is the recommended way to use async subscriptions. It acts as a type-safe wrapper
 * around {@link useAsyncSubscription}, handling the adapter logic for symmetric
 * add/remove listener APIs.
 *
 * Why use this?
 * 1. **Stability:** Eliminates the need for `useCallback` on subscribers.
 * 2. **Simplicity:** Adapts standard symmetric APIs (like `addEventListener`) to the
 * safer asymmetric pattern used internally.
 * 3. **Safety:** Inherits all the race-condition protections of the core hook.
 *
 * @example
 * // Define once at module level
 * const useViewFocused = createAsyncSubscription(
 * 'view-focused',
 * (cb) => fin.me.addEventListener('view-focused', cb),
 * (cb) => fin.me.removeEventListener('view-focused', cb)
 * );
 *
 * // Use in component
 * useViewFocused((event) => console.log(event));
 *
 * @see {@link useAsyncSubscription} for the underlying lifecycle and race-condition logic.
 *
 * @param logIdentifier - Logging identifier for this subscription type.
 * @param subscriber - Function to register the listener.
 * @param unsubscriber - Function to remove the listener.
 * @returns A custom hook that only requires the callback parameter.
 */
export function createAsyncSubscription<T extends (...args: any[]) => void>(
    logIdentifier: string,
    subscriber: SymmetricSubscriber<T>,
    unsubscriber: SymmetricSubscriber<T>
): (callback: T) => void {
    // Create a stable wrapper that adapts the Symmetric API to the Asymmetric API
    const subscriberWrapper: Subscriber<T> = async (cb: T) => {
        await subscriber(cb);
        return async () => {
            await unsubscriber(cb);
        };
    };

    return function useCustomAsyncSubscription(callback: T) {
        useAsyncSubscription<T>(logIdentifier, subscriberWrapper, callback);
    };
}
