import { useContext, useEffect } from 'react';
import { useSelector } from 'react-redux';

import styled from 'styled-components';

import { enterpriseStyles } from '@openfin/ui-library/enterprise-css-selectors';

import { containerId } from '@common/utils/layout';

import { AttachedPageInternal } from '@common/api/pages/shapes';

import { selectActivePage, selectPages } from '@enterprise/slices/pages/attached';

import { selectSelectedViewsForPage } from '@enterprise/slices/tab-focus';

import { BrowserLayoutDragContext } from '@common/hooks/context';
import { useFindInPageBrowserWindow } from '@common/hooks/find-in-page/useFindInPageBrowserWindow';
import store from '@enterprise/store';

import LayoutContainer from './LayoutContainer';

import '@openfin/ui-library/enterprise/layouts/layouts.css';

const ContainerContainer = styled.div`
    flex: 1;
    /* This overflow is !super important! GL cant seem to calculate its dimensions without it! */
    overflow: hidden;
    padding: 0px;
    position: absolute;
    width: 100%;
    height: 100%;
`;

export default function LayoutContainerWrapper() {
    const pages: AttachedPageInternal[] = useSelector(selectPages);
    const activePage = useSelector(selectActivePage);

    const { isAcceptingLayoutDrag } = useContext(BrowserLayoutDragContext);

    const findInPageModal = useFindInPageBrowserWindow({ selectActivePage, selectSelectedViewsForPage, store });

    const onDragBlockerDragOver = (event: React.DragEvent<HTMLDivElement>) => {
        event.preventDefault();
        event.stopPropagation();
    };

    useEffect(() => {
        // Initialize the find in page modal view only once
        findInPageModal.initialize();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    return (
        <ContainerContainer id={containerId} className={enterpriseStyles.layoutsContainer}>
            {pages.map((page, index) => {
                return (
                    <LayoutContainer
                        key={page.layoutContainerKey}
                        layoutContainerKey={page.layoutContainerKey}
                        pageId={page.pageId}
                        pageIndex={index}
                        active={page.pageId === activePage.pageId}
                        findInPageModal={findInPageModal}
                    />
                );
            })}
            {!isAcceptingLayoutDrag && <DragBlockerOverlay onDragOver={onDragBlockerDragOver}></DragBlockerOverlay>}
        </ContainerContainer>
    );
}

const DragBlockerOverlay = styled.div`
    position: absolute;
    width: 100%;
    height: 100%;
    z-index: 1;
`;
