import { MutableRefObject, useCallback, useContext, useEffect, useRef } from 'react';
import { useSelector } from 'react-redux';

import OpenFin from '@openfin/core';

import debounce from 'lodash.debounce';

import { createFindInPageChannel } from '@common/utils/find-in-page/findInPageChannel';
import { mapContentComponentState } from '@common/utils/layout';
import { BrowserSearchMenuKeyboardEvent, SearchMenuChannelMessage } from '@common/utils/popup-window';
import { currentOFIdentity } from '@common/utils/window';

import type { AttachedPageInternal } from '@common/api/pages/shapes';

import { selectIsActivePageChanging } from '@enterprise/slices/pages/attached';

import { SearchMenuChannel } from '@enterprise/components/ControlBar/LeftControlsContainer/EnterpriseNavigationContainer/AddressBar/AddressBar';

import {
    SearchViewExpansionState,
    WindowSearchMenuContext
} from '@enterprise/context/SearchMenu/WindowSearchMenuContext';

/**
 * Custom hook that sends messages to the search view with updates about the browser window's views, search text changes, and whether
 * the address search view should expand.
 *
 * @param selectedViews - Array of currently selected views in the browser window.
 * @param searchMenuChannel - Ref object containing a function to send messages to the search view.
 * @param activePage - Object representing the currently active page in the browser window.
 * @param searchText - String representing the current text in the address input.
 * @param inputContainerRef - Ref object pointing to the input container element.
 * @returns Object containing a function to send keyboard events to the search menu view.
 */
export const usePostMessageToSearchMenuView = (
    selectedViews: OpenFin.Identity[],
    searchMenuChannel: SearchMenuChannel,
    activePage: AttachedPageInternal,
    searchText: string,
    inputContainerRef: MutableRefObject<HTMLDivElement>
) => {
    const { shouldExpandMenu } = useContext(WindowSearchMenuContext);
    const isActivePageChanging = useSelector(selectIsActivePageChanging);
    const SEARCH_DEBOUNCE_MS = 150;
    const prevShouldExpandMenu = useRef<boolean>(false);

    useEffect(() => {
        (async () => {
            if (!isActivePageChanging && activePage.layoutContainerKey && selectedViews?.length) {
                const layout = fin.Platform.Layout.wrapSync({
                    ...fin.me.identity,
                    layoutName: activePage.layoutContainerKey
                });
                const layoutConfig = await layout.getConfig();
                const openViews = mapContentComponentState(layoutConfig.content).map((viewOptions) => {
                    return fin.View.wrapSync({ name: viewOptions.name, uuid: currentOFIdentity.uuid }).identity;
                });

                searchMenuChannel.postMessage({
                    type: 'update-search-menu-state',
                    selectedViews,
                    openViews,
                    windowId: fin.me.identity,
                    offsetLeft: inputContainerRef.current.offsetLeft
                } as SearchMenuChannelMessage);
            }
        })();
    }, [
        isActivePageChanging,
        selectedViews,
        searchText,
        activePage.layoutContainerKey,
        searchMenuChannel,
        inputContainerRef
    ]);

    const debouncedSendSearchUpdate = useCallback(
        debounce(
            (payload: {
                text?: string;
                shouldExpand?: SearchViewExpansionState;
                keyboardEvent?: BrowserSearchMenuKeyboardEvent;
                offsetLeft?: number;
            }) => {
                const { text, shouldExpand, keyboardEvent } = payload;
                searchMenuChannel.postMessage({
                    type: 'update-search-menu-state',
                    shouldExpandMenu: shouldExpand,
                    searchText: text,
                    keyboardEvent,
                    offsetLeft: payload.offsetLeft
                } as SearchMenuChannelMessage);
            },
            SEARCH_DEBOUNCE_MS,
            { leading: true, trailing: true }
        ),
        [searchMenuChannel]
    );

    useEffect(() => {
        const { offsetLeft } = inputContainerRef.current;
        debouncedSendSearchUpdate({ text: searchText, shouldExpand: shouldExpandMenu, offsetLeft });

        // Skip the debounce when closing or opening via click to avoid race conditions with view-focused events
        if (!shouldExpandMenu.shouldExpand || shouldExpandMenu.method === 'click') {
            debouncedSendSearchUpdate.flush();
        } else if (!prevShouldExpandMenu.current && shouldExpandMenu.shouldExpand) {
            // Search menu is transitioning from collapsed to expanded, hide find-in-page
            (async () => {
                try {
                    const findInPageChannel = await createFindInPageChannel();
                    findInPageChannel.postMessage({ type: 'hide-from-search-menu' });
                    findInPageChannel.close();
                } catch (error) {
                    console.error('Error hiding find-in-page:', error);
                }
            })();
        }

        // Update previous state
        prevShouldExpandMenu.current = shouldExpandMenu.shouldExpand;
    }, [debouncedSendSearchUpdate, shouldExpandMenu, searchText, searchMenuChannel, inputContainerRef]);

    const sendKeyboardEventToSearchMenuView = useCallback(
        async (keyboardEvent: BrowserSearchMenuKeyboardEvent) => {
            if (keyboardEvent.options.key === 'Enter') {
                debouncedSendSearchUpdate.flush();
            }
            debouncedSendSearchUpdate({ keyboardEvent });
        },
        [debouncedSendSearchUpdate]
    );

    return { sendKeyboardEventToSearchMenuView };
};
