import { useEffect, useRef } from 'react';

import { Icon } from '@openfin/ui-library';

import { enterpriseNavigationTestIds } from '@common/utils/test-ids';

import useSystemSchemeCheck from '@common/hooks/useSystemSchemeCheck';
import { useIsSelectedViewNavigated } from '@enterprise/hooks/EnterpriseSearchMenu/useIsSelectedViewNavigated';
import { useSetUpZoomHotkeys } from '@enterprise/hooks/useSetUpZoomHotkeys';
import { useZoomControlsDialog } from '@enterprise/hooks/useZoomControlsDialog';

import { IconContainer } from './IconContainer';

type ZoomButtonProps = {
    url?: string;
    isMenuExpanded?: boolean;
    zoomButtonRef: React.MutableRefObject<HTMLDivElement>;
    onRenderChange?: (isRendered: boolean) => void;
};

export const ZoomButton = ({ url, onRenderChange, isMenuExpanded, zoomButtonRef }: ZoomButtonProps) => {
    const zoomPercentRef = useRef(100);
    const { isSchemeDark } = useSystemSchemeCheck();
    const { selectedView } = useIsSelectedViewNavigated({ url });
    const { showDialog, isDialogShown } = useZoomControlsDialog(
        zoomButtonRef,
        selectedView,
        zoomPercentRef,
        isMenuExpanded
    );
    useSetUpZoomHotkeys({ selectedView, zoomPercentRef, showDialog });

    const shouldRender = (isDialogShown || zoomPercentRef.current !== 100) && !isMenuExpanded;

    useEffect(() => {
        onRenderChange?.(shouldRender);
    }, [shouldRender, onRenderChange]);

    const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
        if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault();
            showDialog(true);
        }
    };

    return (
        <IconContainer
            isSchemeDark={isSchemeDark}
            onClick={() => showDialog(true)}
            onKeyDown={handleKeyDown}
            isDialogShown={isDialogShown}
            ref={zoomButtonRef}
            shouldRender={shouldRender}
            tabIndex={shouldRender ? 0 : -1}
            role="button"
            aria-label="Open zoom controls"
            data-testid={enterpriseNavigationTestIds.zoomButton}
        >
            <Icon icon="ZoomInIcon" />
        </IconContainer>
    );
};
