import { t } from '@common/api/i18next';
import { getTabsHandler } from '@common/api/tabs';

import { BrowserButtonType, ToolbarOptions, WindowStateButtonOptions } from '@client-platform/shapes';

export const handleMinimizeClick = () => {
    getCurrentOFWindow()
        .minimize()
        .catch((err) => {
            console.error(`RightControlsContainer: Failed to minimize: ${err}`);
        });
};

export const handleShowHideTabs = async (layoutIdentity: OpenFin.LayoutIdentity) => {
    const tabHandler = getTabsHandler(layoutIdentity);
    const isShowing = await tabHandler.isShowingTabs();
    if (isShowing) {
        await tabHandler.hide();
    } else {
        await tabHandler.show();
    }
    showSuccess({
        message: t(isShowing ? 'successIndicator.hidden' : 'successIndicator.shown'),
        parentBrowserName: currentOFIdentity.name
    });
    await fin.me.focus();
};

