import { MutableRefObject, useCallback, useContext, useEffect, useRef, useState } from 'react';
import { useSelector } from 'react-redux';

import type OpenFin from '@openfin/core';

import { createInlineDebugLogger } from '@common/utils/debug-log';
import { connectToZoomControlsDialogChannel } from '@common/utils/enterprise-channels';
import { ZOOM_DIALOG_CHANNEL_ACTION, ZoomControlsDialogStateMessage } from '@common/utils/popup-window';
import Route from '@common/utils/route';
import { getWindowBounds, WindowName } from '@common/utils/window';

import { selectIsActivePageChanging } from '@enterprise/slices/pages/attached';

import { ZoomUtils } from '@enterprise/utils/zoom-controls';

import { BrowserTypeContext } from '@common/hooks/context';
import { createAsyncSubscription } from '@common/hooks/useAsyncSubscription';
import usePreloadedWindow from '@common/hooks/usePreloadedWindow';
import { useWithWindowStyleOverride } from '@common/hooks/useWindowFocusState';

import { useIsWindows } from './useIsWindows';

const logZoomDebug = createInlineDebugLogger('zoom-debug');

const ZOOM_DIALOG_WINDOW_DIMENSIONS = {
    defaultWidth: 193,
    defaultHeight: 48
};

const getZoomWindowHandle = () =>
    fin.Window.wrapSync({ uuid: fin.me.identity.uuid, name: WindowName.ZoomControlsDialog });

const useIsHiddenSubscription = createAsyncSubscription(
    'zoomControlsDialog-hidden',
    (cb: () => void) => getZoomWindowHandle().addListener('hidden', cb),
    (cb: () => void) => getZoomWindowHandle().removeListener('hidden', cb)
);

/**
 * One of the requirements for the zoom dialog is that the window must not be focused when the dialog is opened, unless the user interacts with it.
 * Mac and Windows handle this behavior differently of having a window open but not focused.
 * On Mac, the behavior mirrors the behavior as if the window is focused. So when you click anywhere but the zoom dialog window, the dialog window is blurred.
 * On Windows, when the dialog is open and not focused, clicks outside of the dialog window do not trigger the blur event. So we have to set up our own listeners for these events.
 *
 * This function sets up the necessary listeners to hide the dialog window when the user interacts outside of it.
 *
 * @param zoomWindow
 * @param browserWindow
 * @param selectedView
 * @param resolve
 */
const setUpBlurListenersForWindows = async (
    zoomWindow: OpenFin.Window,
    browserWindow: OpenFin.Window,
    selectedView: OpenFin.View,
    resolve: () => void,
    openedViaMouseClick: boolean
) => {
    const app = fin.Application.getCurrentSync();

    const hideZoomWindow = async () => {
        logZoomDebug('browser:hideZoomWindow');
        await zoomWindow.hide();
    };

    const blurListener = async () => {
        const currentFocusedWindow = await fin.System.getFocusedWindow();
        logZoomDebug('browser:blurListener', {
            focusedWindow: currentFocusedWindow?.name ?? null
        });
        // hide the zoom window ony if it isn't already focused or no window in this runtime is focused
        if (!currentFocusedWindow || currentFocusedWindow.name !== WindowName.ZoomControlsDialog) {
            hideZoomWindow();
        }
    };

    const appWindowFocusedListener = ({ name }: OpenFin.Identity) => {
        logZoomDebug('browser:app-window-focused', {
            focusedWindow: name,
            browserWindow: browserWindow.identity.name
        });
        // Windows can miss expected blur signals for non-activated popup windows.
        // Ensure the dialog closes when focus moves to any other window in this app.
        if (name !== browserWindow.identity.name && name !== WindowName.ZoomControlsDialog) {
            hideZoomWindow();
        }
    };

    const viewFocusedListener = (event: Extract<OpenFin.WindowEvents.WindowEvent, { type: 'view-focused' }>) => {
        const focusedViewName = event.viewIdentity?.name;
        logZoomDebug('browser:view-focused', {
            focusedView: focusedViewName ?? null
        });

        // Hide zoom controls when address search view takes focus.
        if (focusedViewName?.startsWith(WindowName.BrowserAddressSearchPrefix)) {
            hideZoomWindow();
        }
    };

    await zoomWindow.once('hidden', () => {
        logZoomDebug('browser:zoom-hidden-cleanup');
        resolve();
        window.removeEventListener('mousedown', hideZoomWindow);
        browserWindow.removeListener('bounds-changing', hideZoomWindow);
        browserWindow.removeListener('maximized', hideZoomWindow);
        browserWindow.removeListener('minimized', hideZoomWindow);
        browserWindow.removeListener('restored', hideZoomWindow);
        browserWindow.removeListener('blurred', blurListener);
        browserWindow.removeListener('view-focused', viewFocusedListener);
        app.removeListener('window-focused', appWindowFocusedListener);
        selectedView.removeListener('blurred', blurListener);
    });

    // Always hide if the parent window moves/resizes/state-changes so the dialog never appears "detached".
    browserWindow.addListener('bounds-changing', hideZoomWindow);
    browserWindow.addListener('maximized', hideZoomWindow);
    browserWindow.addListener('minimized', hideZoomWindow);
    browserWindow.addListener('restored', hideZoomWindow);

    // Always hide when the parent browser window blurs (e.g. switching to another browser window).
    browserWindow.on('blurred', blurListener);
    browserWindow.on('view-focused', viewFocusedListener);
    app.addListener('window-focused', appWindowFocusedListener);

    /**
     * For mouse-opened dialogs, preserve existing outside-interaction behavior.
     * For hotkey-opened dialogs, avoid selected-view blur/mousedown auto-hide so
     * focus changes between side-by-side views can still push updated zoom state.
     */
    if (openedViaMouseClick) {
        window.addEventListener('mousedown', hideZoomWindow);
        selectedView.on('blurred', blurListener);
    }
};

/*
 * This hook is used to show the zoom controls dialog when the user clicks on the zoom button in the address bar..
 * @param zoomButtonRef - The ref of the zoom button element
 * @param selectedView - The selected view to zoom
 * @param zoomPercentRef - The ref of the zoom percent
 * @returns {showDialog, isDialogShown}
 */
export const useZoomControlsDialog = (
    zoomButtonRef: MutableRefObject<HTMLElement | null>,
    selectedView: OpenFin.View | null,
    zoomPercentRef: MutableRefObject<number>,
    isMenuExpanded: boolean
) => {
    const [isShowingFromThisWindow, setIsShowingFromThisWindow] = useState(false);
    const channelRef = useRef<OpenFin.ChannelClient | null>(null);
    const withWindowStyleOverride = useWithWindowStyleOverride();
    const isWindows = useIsWindows();

    const lastSyncedViewRef = useRef<OpenFin.Identity | null>(null);

    const isActivePageChanging = useSelector(selectIsActivePageChanging);

    usePreloadedWindow({
        windowName: WindowName.ZoomControlsDialog,
        route: Route.ZoomControlsDialog,
        shouldPreload: useContext(BrowserTypeContext).isEnterprise,
        windowCreationOptions: {
            ...ZOOM_DIALOG_WINDOW_DIMENSIONS,
            alwaysOnTop: isWindows && true,
            cornerRounding: isWindows && {
                height: 4,
                width: 4
            }
        }
    });

    useIsHiddenSubscription(() => setIsShowingFromThisWindow(false));

    const dispatchZoomState = useCallback(
        async (selectedViewIdentity: OpenFin.Identity, zoomPercent: number, openedViaMouseClick = false) => {
            if (!channelRef.current) {
                return;
            }

            const browserWindowBounds = await getWindowBounds(fin.me as OpenFin.Window);
            const zoomButtonRect = zoomButtonRef.current?.getBoundingClientRect();

            if (!zoomButtonRect) {
                return;
            }

            const x = browserWindowBounds.left + zoomButtonRect.right - ZOOM_DIALOG_WINDOW_DIMENSIONS.defaultWidth;
            const y = browserWindowBounds.top + zoomButtonRect.top + zoomButtonRect.height;

            const messageData = {
                parentIdentity: fin.me.identity,
                x,
                y,
                payload: { selectedViewIdentity, zoomPercent, openedViaMouseClick }
            } satisfies ZoomControlsDialogStateMessage;

            // used to discriminate multiple browser windows' AddressBar > ZoomButton to only show the icon
            // when the current window was the one requesting the dialog
            setIsShowingFromThisWindow(true);
            await channelRef.current.dispatch(ZOOM_DIALOG_CHANNEL_ACTION, messageData);
        },
        [zoomButtonRef]
    );

    const showDialog = useCallback(
        async (openedViaMouseClick = false) => {
            logZoomDebug('browser:showDialog-called', {
                openedViaMouseClick,
                hasSelectedView: !!selectedView,
                isMenuExpanded
            });
            if (isMenuExpanded || !selectedView) {
                return;
            }

            if (!channelRef.current) {
                channelRef.current = await connectToZoomControlsDialogChannel();
            }

            const zoomWindow = getZoomWindowHandle();

            const browserWindow = fin.me as OpenFin.Window;

            const setUpBlurListenerAndOpenDialog = async (targetIdentity: OpenFin.Identity, resolve: () => void) => {
                /**
                 * Each time one of the zoom hotkey is pressed, showDialog is called.
                 * So if the dialog is already open, we do not want to set up these listeners again.
                 */
                if (!isShowingFromThisWindow) {
                    if (isWindows) {
                        logZoomDebug('browser:setup-windows-listeners', {
                            selectedView: selectedView.identity.name,
                            openedViaMouseClick
                        });
                        await setUpBlurListenersForWindows(
                            zoomWindow,
                            browserWindow,
                            selectedView,
                            resolve,
                            openedViaMouseClick
                        );
                    } else {
                        await zoomWindow.once('blurred', () => {
                            resolve();
                        });
                    }
                } else {
                    // dialog is already open, don't leak the promise
                    resolve();
                }

                logZoomDebug('browser:dispatchZoomState', {
                    selectedView: targetIdentity?.name,
                    openedViaMouseClick
                });
                await dispatchZoomState(targetIdentity, zoomPercentRef.current, openedViaMouseClick);
            };

            // withWindowStyleOverride will style the browser window as focused until the promise resolves (when the dialog is hidden)
            withWindowStyleOverride('focused', async () => {
                await new Promise<void>((resolve) => {
                    setUpBlurListenerAndOpenDialog(selectedView.identity, resolve);
                });
            });
        },
        [
            isMenuExpanded,
            selectedView,
            isShowingFromThisWindow,
            withWindowStyleOverride,
            zoomPercentRef,
            isWindows,
            dispatchZoomState
        ]
    );

    // this effect seeds our zoom level percent, it handles the case where the view is not loaded yet
    useEffect(() => {
        const checkZoomLevel = async () => {
            if (selectedView) {
                const level = await selectedView.getZoomLevel();
                zoomPercentRef.current = ZoomUtils.levelToPercent(level);
            }
        };

        const checkZoomLevelWithOptions = async () => {
            if (selectedView) {
                const opts = await selectedView.getOptions();
                zoomPercentRef.current = ZoomUtils.levelToPercent(opts.zoomLevel);
            }
        };

        checkZoomLevel();

        if (selectedView) {
            // This listener gets the correct zoom level on a newly opened view.
            // getZoomLevel() does not get the correct zoom level until it is applied which can be after the view is loaded.
            // This is a workaround until we get zoom eventing from core.
            selectedView.once('did-finish-load', checkZoomLevelWithOptions);
        }

        return () => {
            if (selectedView) {
                selectedView.removeListener('did-finish-load', checkZoomLevelWithOptions);
            }
        };
    }, [selectedView, zoomPercentRef]);

    useEffect(() => {
        if (!isActivePageChanging) return;

        // hide the zoom window on supertab switch
        getZoomWindowHandle()
            .hide()
            .catch((error) => {
                console.error('Error hiding zoom dialog during supertab switch:', error);
            });
    }, [isActivePageChanging]);

    useEffect(() => {
        if (!isMenuExpanded || !isShowingFromThisWindow) {
            return;
        }

        logZoomDebug('browser:hide-on-menu-expand');
        getZoomWindowHandle()
            .hide()
            .catch((error) => {
                console.error('Error hiding zoom dialog during menu expansion:', error);
            });
    }, [isMenuExpanded, isShowingFromThisWindow]);

    useEffect(() => {
        if (!isShowingFromThisWindow || isMenuExpanded || !channelRef.current || isActivePageChanging) {
            return;
        }

        const syncDialogWithFocusedView = async () => {
            try {
                const identityForSync = selectedView?.identity;
                // if the identity for sync is the same as the last synced identity, don't sync again
                // prevents accidentally re-showing the zoom dialog when it just disappeared and
                // the user clicked the same view
                if (!identityForSync || lastSyncedViewRef.current?.name === identityForSync.name) {
                    logZoomDebug('browser:syncDialogWithFocusedView:skip-sync', {
                        identityForSync: identityForSync?.name,
                        lastSyncedView: lastSyncedViewRef.current?.name
                    });
                    return;
                }

                logZoomDebug('browser:syncDialogWithFocusedView', {
                    identityForSync: identityForSync?.name,
                    lastSyncedView: lastSyncedViewRef.current?.name
                });

                lastSyncedViewRef.current = identityForSync;
                const view = fin.View.wrapSync(identityForSync);
                const level = await view.getZoomLevel();
                zoomPercentRef.current = ZoomUtils.levelToPercent(level);

                await dispatchZoomState(identityForSync, zoomPercentRef.current);
            } catch (error) {
                console.error('Error syncing zoom dialog with selected view:', error);
            }
        };

        syncDialogWithFocusedView();
    }, [
        dispatchZoomState,
        isShowingFromThisWindow,
        isMenuExpanded,
        selectedView,
        zoomPercentRef,
        isActivePageChanging
    ]);

    useEffect(() => {
        // Cleanup function to disconnect from the channel when the component unmounts
        return () => {
            if (channelRef.current) {
                channelRef.current.disconnect();
                channelRef.current = null; // Clean up the ref
            }
        };
    }, []);

    return { showDialog, isDialogShown: isShowingFromThisWindow };
};
