import React, { forwardRef, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { useSelector } from 'react-redux';

import styled from 'styled-components';

import type OpenFin from '@openfin/core';

import { Box, Icon, Mixins } from '@openfin/ui-library';
import { enterpriseStyles } from '@openfin/ui-library/enterprise-css-selectors';

import { getLandingPageUrls, makeNewLandingPage } from '@common/utils/landing-page';
import { getLayoutWithSingleView } from '@common/utils/layout';
import {
    decodeDragPayload,
    encodeDragPayload,
    getDragPayloadType,
    getDragState,
    getReorderedPages,
    getViewTabPayload,
    hideSingleView,
    isSingleViewDrag,
    isWithinParentBounds,
    setDragState
} from '@common/utils/page-drag';
import { enterprisePageTestIds } from '@common/utils/test-ids';
import { raiseBrowserAnalytics } from '@common/utils/usage-register';
import { currentOFIdentity } from '@common/utils/window';

import { useTranslation } from '@common/api/i18next';
import { makePage } from '@common/api/pages';
import type { AttachedPageInternal, Page, ReparentAttachedPage } from '@common/api/pages/shapes';

import { selectIsModalOpen } from '@common/slices/modal';

import { ScreenReaderAnnouncement } from '@common/components/Accessibility/ScreenReaderAnnouncement';
import BaseButton from '@common/components/BaseButton/BaseButton';
import { scrollbarStyles, ScrollShadow } from '@common/components/Scroll/Scroll';

import { getPageWithLayout } from '@enterprise/api/pages/attached';
import { dispatch, getState } from '@enterprise/api/pages/state';
import {
    selectActivePage,
    selectIsActivePageChanging,
    selectIsInitialized,
    selectPageByLayoutContainerKey,
    selectPages,
    updatePageAtIndex
} from '@enterprise/slices/pages/attached';

import { updatePageForViewCount } from '@enterprise/utils/layout';

import { requestClosePage } from '@enterprise/api/controls';

import { selectSelectedViewsForPage } from '@enterprise/slices/tab-focus';

import { useManagePageViewCount } from '@enterprise/components/ControlBar/Tablist/useManagePageViewCount';

import { getCurrentSync } from '@client-platform/api';
import { BrowserLayoutDragContext } from '@common/hooks/context';
import { useViewFocusCoordination } from '@common/hooks/useViewFocusCoordination';
import useWindowFocusState from '@common/hooks/useWindowFocusState';
import { useWindowOptions } from '@common/hooks/useWindowOptions';
import { useGetContextGroups } from '@enterprise/hooks/useGetContextGroups';
import { usePageDrag } from '@enterprise/hooks/usePageDrag';
import { usePageIcon } from '@enterprise/hooks/usePageIcon';
import useWindowTitle from '@enterprise/hooks/useWindowTitle';
import type { BrowserRootState } from '@enterprise/store';

import PageButton from './PageButton/PageButton';
import TextSpan from './TextSpan';
import {
    bringWindowToFront,
    deriveWorkspaceWindowOpts,
    getNextActivePageOnRemoval,
    handleTabContainerScroll,
    hideGoldenLayoutsDragIndicators,
    mergeViewIntoTargetPage
} from './utils';
import WithDropIndicator, { DropIndicatorStyles } from './WithDropIndicator';

import '@openfin/ui-library/enterprise/tabs/tabs.css';

const SCROLL_SHADOW_OFFSET = 32;

const Tablist = (): JSX.Element => {
    const isEnterprise = true;
    const { t } = useTranslation();

    const windowFocused = useWindowFocusState();
    const singlePageWindowTabTitle = useWindowTitle();

    /* Pages */
    const pages = useSelector(selectPages);
    const activePage: AttachedPageInternal | undefined = useSelector(selectActivePage);

    const focusedViewInActivePage = useSelector((state: BrowserRootState) =>
        selectSelectedViewsForPage(state, activePage?.pageId)
    ).at(0);

    const isPagesInitialized = useSelector(selectIsInitialized);
    const {
        onPageDragOver,
        dropIndicatorPosition,
        isShowingDropIndicator,
        setIsShowingDropIndicator,
        hoveredPageIndex
    } = usePageDrag(pages);

    const containerRef = useRef<HTMLDivElement>(null);
    const tabContainerRef = useRef<HTMLDivElement>(null);
    const plusButtonBlock = React.useRef<boolean>(false);

    /**
     * When there are enough page tabs that the tab container becomes scrollable, render the scroll shadows.
     */
    const [shouldShowScrollShadows, setShouldShowScrollShadows] = useState<boolean>(false);
    /**
     * Keeps track of the current page, if any, is being dragged around.
     * This will only be set if the drag is from our window, not for any in flight 'drag overs' from other windows.
     */
    const [currentDragPageId, setCurrentDragPageId] = React.useState<string | null>(null);
    const [screenReaderAnnouncement, setScreenReaderAnnouncement] = useState<string>('');

    const { setIsAcceptingLayoutDrag } = useContext(BrowserLayoutDragContext);

    const { workspacePlatform } = useWindowOptions();
    const workspaceWindowOptions = useMemo(() => deriveWorkspaceWindowOpts(workspacePlatform), [workspacePlatform]);

    const updateTablistAttrs = useCallback(() => {
        setShouldShowScrollShadows(tabContainerRef.current.clientWidth < tabContainerRef.current.scrollWidth);
    }, []);

    const isModalOpen = useSelector(selectIsModalOpen);
    const isActivePageChanging = useSelector(selectIsActivePageChanging);

    const isNewTabButtonVisible =
        !workspaceWindowOptions.isLocked && workspaceWindowOptions.isNewPageButtonEnabled && isPagesInitialized;

    useViewFocusCoordination({
        activePage,
        focusedViewInActivePage,
        isModalOpen,
        isEnterprise: true,
        isActivePageChanging
    });

    useEffect(() => {
        window.addEventListener('resize', updateTablistAttrs);
        return () => window.removeEventListener('resize', updateTablistAttrs);
    }, [updateTablistAttrs]);

    useEffect(() => {
        updateTablistAttrs();
    }, [pages.length, updateTablistAttrs]);

    const updatePageForViewCountListener = useCallback(
        async (layoutContainerKey?: string) => {
            if (layoutContainerKey !== undefined) {
                const pageForLayout = selectPageByLayoutContainerKey(getState(), layoutContainerKey);
                if (pageForLayout?.pageId) {
                    updatePageForViewCount(pageForLayout);
                }
                return;
            }
            if (activePage?.pageId) {
                updatePageForViewCount(activePage);
            }
        },
        [activePage]
    );

    useManagePageViewCount(updatePageForViewCountListener, activePage?.layoutContainerKey);

    const onPageClickHandler = useCallback(
        async (page: Page) => {
            if (activePage?.pageId !== page.pageId) {
                await getCurrentSync().Browser.wrapSync(currentOFIdentity).setActivePage(page.pageId);
            }
        },
        [activePage]
    );

    useEffect(() => {
        if (currentDragPageId === activePage.pageId) {
            setIsAcceptingLayoutDrag(false);
        } else {
            setIsAcceptingLayoutDrag(true);
        }
    }, [activePage?.pageId, currentDragPageId]);

    const onPlusClickHandler = useCallback(async () => {
        if (plusButtonBlock.current) return;

        plusButtonBlock.current = true;
        const newPage = await makeNewLandingPage();
        const browser = getCurrentSync().Browser.wrapSync(currentOFIdentity);
        const { newPageUrl } = await getLandingPageUrls();
        // Ensure that actualNewPageUrl is undefined if newPageUrl is false
        const actualNewPageUrl = newPageUrl ? newPageUrl : undefined;

        try {
            setScreenReaderAnnouncement(
                `New tab ${newPage.title ? newPage.title : ''} added. The tab group now has ${pages.length + 1} tabs.`
            );
            // eslint-disable-next-line no-underscore-dangle
            await browser._addDefaultPage({ identity: currentOFIdentity, page: newPage, newPageUrl: actualNewPageUrl });
            raiseBrowserAnalytics({
                type: 'Page Section',
                action: 'Select New Page',
                value: 'New Page',
                skipValueHashing: true
            });
        } catch (error) {
            console.error('Failed to add new page', error);
        } finally {
            // if page add has failed we still want to allow to add new pages.
            plusButtonBlock.current = false;
        }
    }, [pages.length]);

    const onPageDragStartHandler = useCallback(
        async (event: React.DragEvent<HTMLDivElement>, page: Page) => {
            if (workspaceWindowOptions.preventPageDrag) {
                event.preventDefault();
                return;
            }

            if (selectPages(getState()).length > 1 && !workspaceWindowOptions.preventPageDragOut) {
                const original = event.target as HTMLElement;
                const originalRect = original.getBoundingClientRect();

                // Create a clone of the element
                // This is used as the drag image
                const clone = (event.target as HTMLElement).cloneNode(true) as HTMLElement;
                clone.style.cssText = `
                    position: absolute;
                    top: -99999px; /* Hide the clone from the viewport */
                    height: ${originalRect.height}px;
                    width: ${originalRect.width}px;
                `;
                if (activePage.pageId !== page.pageId && original.scrollWidth > 72) {
                    clone.classList.add('dragging-page-clone');
                }
                document.body.appendChild(clone);

                // Use the clone as the drag image
                event.dataTransfer.setDragImage(clone, 0, 0);
                // Add a class to the original element to indicate it is being dragged
                // Needed to add a delay to ensure the resize of the original element does not affect the drag operation
                // Without it, if your mouse grabs the tab outside of the resized area, the item is dropped and the drag state is frozen

                // Remove the clone from the document after the drag operation is complete
                setTimeout(() => document.body.removeChild(clone), 0);
            }

            if (!workspaceWindowOptions.preventPageDragOut) {
                event.dataTransfer.setData(
                    getDragPayloadType(isEnterprise),
                    JSON.stringify({ identity: fin.me.identity, id: page.pageId })
                );
            }

            // Enterprise: Prepare single-view page for dragging into layout
            if ('content' in page.layout.content[0] && page.layout.content.length === 1) {
                const component = page.layout.content[0].content[0];
                if (
                    'componentState' in component &&
                    'componentName' in component &&
                    component.componentName === 'view'
                ) {
                    const viewOptions = component.componentState;
                    const identityString = JSON.stringify([
                        JSON.stringify(viewOptions),
                        currentOFIdentity.uuid,
                        viewOptions.name
                    ]);
                    event.dataTransfer.effectAllowed = 'linkMove';
                    event.dataTransfer.setData('view-identity', identityString);

                    const layoutSettings = page.layout.settings;
                    const encodedJson = encodeDragPayload({
                        sourceIdentity: { uuid: currentOFIdentity.uuid, name: viewOptions.name },
                        settings: {
                            preventDragOut: layoutSettings.preventDragOut || viewOptions.preventDragOut
                        }
                    });

                    event.dataTransfer.setData(encodedJson, 'true');
                }
            }

            // reset to reorder at the beginning of a drag
            setDragState('reorder');
            /**
             * To accept layout drags when hovering over views, need to have views ignore mouse events.
             * The events will instead be passed to parent window.
             */
            fin.me.wire.sendAction('set-ignore-all-view-mouse-events', {
                enabled: true
            });
            // this hides the dragging element in the DOM, need to do this in a timeout otherwise drag operation will be stopped
            setTimeout(() => {
                setCurrentDragPageId(page.pageId);
            }, 0);

            event.dataTransfer.setData('of-drag-cursor-name', 'pointer');
            raiseBrowserAnalytics({
                type: 'Page Tab',
                action: 'Drag Page',
                value: page.title,
                data: { uuid: page.pageId }
            });
        },
        [
            activePage?.pageId,
            workspaceWindowOptions.preventPageDrag,
            workspaceWindowOptions.preventPageDragOut,
            isEnterprise
        ]
    );

    const onDragEnterHandler = useCallback(
        (event: React.DragEvent<HTMLDivElement>) => {
            event.stopPropagation();
            event.preventDefault();
            bringWindowToFront();
            let encodedDropType = undefined;
            const viewTabPayload = event.dataTransfer.types.find((type) => type.startsWith('payload'));
            const highLevelTabPayload = event.dataTransfer.types.find((type) =>
                type.startsWith(getDragPayloadType(isEnterprise))
            );
            if (viewTabPayload) {
                encodedDropType = decodeDragPayload(viewTabPayload);
                hideGoldenLayoutsDragIndicators();
            }

            if (!workspaceWindowOptions.isLocked && (highLevelTabPayload || encodedDropType)) {
                setIsShowingDropIndicator(true);
                // a page from another window is being dragged
                if (!currentDragPageId && !workspaceWindowOptions.preventPageDragIn) {
                    setDragState('reparent');
                } else if (currentDragPageId) {
                    // dragging a page from current window
                    setDragState('reorder');
                }
            }
        },
        [
            workspaceWindowOptions.isLocked,
            workspaceWindowOptions.preventPageDragIn,
            isEnterprise,
            setIsShowingDropIndicator,
            currentDragPageId
        ]
    );

    const onDragLeaveHandler = useCallback(
        (event: React.DragEvent<HTMLDivElement>) => {
            const isViewDrag = isSingleViewDrag(event);
            const encodedDropType = event.dataTransfer.types.find((type) =>
                type.startsWith(getDragPayloadType(isEnterprise))
            );
            if ((isViewDrag || encodedDropType) && !workspaceWindowOptions.isLocked) {
                // dragleave will fire when dragging over child elements, need to filter out those events
                const isActuallyLeaving = !containerRef.current.contains(event.relatedTarget as HTMLElement);
                if (isActuallyLeaving) {
                    if (isViewDrag) {
                        // Is an enterprise drag that has only one View in it so can be dragged into gl container
                        hideSingleView();
                    }
                    setIsShowingDropIndicator(false);
                    if (encodedDropType) {
                        // Is a page drag from enterprise (and not a view tab drag)
                        setDragState('popout');
                    }
                }
            }
        },
        [workspaceWindowOptions.isLocked, isEnterprise, setIsShowingDropIndicator]
    );

    const onDragOverHandler = useCallback(
        (event: React.DragEvent<HTMLDivElement>) => {
            event.stopPropagation();
            event.preventDefault();
        },
        [workspaceWindowOptions.isLocked]
    );

    const handleSortableSetList = useCallback(
        async (items: { id: string }[]) => {
            // The event is fired even when clicking from one page to another,
            // We only care about changes in order
            const didOrderingChange = () => {
                return items.some(({ id }, index) => id !== pages[index]?.pageId);
            };
            if (!isPagesInitialized || !didOrderingChange()) return;
            await getCurrentSync()
                .Browser.wrapSync(currentOFIdentity)
                .reorderPages({ pageIds: items.map(({ id }) => id) });
        },
        [isPagesInitialized, pages]
    );

    const onDragDropHandler = useCallback(
        async (event: React.DragEvent<HTMLDivElement>) => {
            if (!activePage) {
                console.debug(`TabList::onDragDropHandler - activePage is undefined`);
            }
            // Don't stop propagation for Workspace SDK so Tablist doesn't break view drags
            event.preventDefault();
            event.stopPropagation();

            setIsShowingDropIndicator(false);
            if (workspaceWindowOptions.preventPageDragIn || workspaceWindowOptions.isLocked) {
                return;
            }
            const viewOptionsFromDrag = getViewTabPayload(event);
            if (currentDragPageId && dropIndicatorPosition !== null) {
                // Reordering a page within current window
                const items = getReorderedPages(pages, currentDragPageId, dropIndicatorPosition);
                await handleSortableSetList(items.map((item) => ({ id: item })));
                getCurrentSync().Browser.wrapSync(currentOFIdentity).setActivePage(currentDragPageId);
                setCurrentDragPageId(null);
                return;
            }

            const isPageDropType = event.dataTransfer.types.find((type) =>
                type.startsWith(getDragPayloadType(isEnterprise))
            );
            if (isPageDropType && !currentDragPageId) {
                // dropping a page from a different window

                // Special case: If dropping a single-view page onto a supertab header (hoveredPageIndex !== null && dropIndicatorPosition === null),
                // merge the view into the layout instead of creating a new tab
                if (hoveredPageIndex !== null && dropIndicatorPosition === null && viewOptionsFromDrag) {
                    const targetPage = pages[hoveredPageIndex];
                    await mergeViewIntoTargetPage(targetPage, viewOptionsFromDrag, activePage);
                } else {
                    // Normal case: appending a page to the target window

                    const { id } = JSON.parse(event.dataTransfer.getData(getDragPayloadType(isEnterprise)));
                    const currentWindow = getCurrentSync().Browser.wrapSync(fin.me.identity);
                    // eslint-disable-next-line no-underscore-dangle
                    await currentWindow._reparentPage({ pageId: id, index: dropIndicatorPosition });
                    await currentWindow.setActivePage(id);
                }

                return;
            }

            // Dropping a view or a single view page tab into the tablist
            if (viewOptionsFromDrag) {
                if (dropIndicatorPosition === null && hoveredPageIndex !== null) {
                    // dropIndicatorPosition is null and hoveredPageIndex is not null, so we're dropping a view on a page tab to auto-layout
                    const targetPage = pages[hoveredPageIndex];
                    await mergeViewIntoTargetPage(targetPage, viewOptionsFromDrag, activePage);
                    await getCurrentSync().Browser.wrapSync(currentOFIdentity).setActivePage(targetPage.pageId);
                } else {
                    // dropIndicatorPosition is a real index, so we are creating a page at that index
                    const view = await fin.View.wrap({
                        uuid: viewOptionsFromDrag.uuid,
                        name: viewOptionsFromDrag.name
                    });
                    const viewInfo = await view.getInfo();
                    const updatedViewOptions = {
                        ...viewOptionsFromDrag,
                        url: viewInfo.url,
                        title: viewInfo.title
                    };
                    const config = await getLayoutWithSingleView(
                        updatedViewOptions.title,
                        updatedViewOptions.url,
                        currentOFIdentity
                    );
                    config.content[0].content[0].componentState = updatedViewOptions;

                    // Do not assign the new page a title, as the tab will automatically use the view title
                    const newPage = await makePage(null, config);
                    const browser = getCurrentSync().Browser.wrapSync(currentOFIdentity);
                    // eslint-disable-next-line no-underscore-dangle
                    await browser._addPage(newPage, {
                        index: dropIndicatorPosition,
                        multiInstanceViewBehavior: 'reparent'
                    });

                    await browser.setActivePage(newPage.pageId);

                    // Update the page icon for the new page
                    const updatedPages = selectPages(getState());
                    const matchIndex = updatedPages.findIndex((page) => page?.pageId === newPage.pageId);
                    if (matchIndex !== -1) {
                        dispatch(
                            updatePageAtIndex({
                                index: matchIndex,
                                page: { ...updatedPages[matchIndex], pageIcon: viewInfo.favicons[0] }
                            })
                        );
                    }

                    if (activePage) {
                        updatePageForViewCount(activePage);
                    }
                }
            }
        },
        [
            workspaceWindowOptions.isLocked,
            workspaceWindowOptions.preventPageDragIn,
            isEnterprise,
            dropIndicatorPosition,
            hoveredPageIndex,
            setIsShowingDropIndicator,
            activePage,
            pages,
            currentDragPageId,
            handleSortableSetList
        ]
    );

    const onPageDragEndHandler = useCallback(
        async (event: DragEvent) => {
            // This needs to be done before anything else to ensure views can receive mouse events if code below errors for some reason
            await fin.me.wire.sendAction('set-ignore-all-view-mouse-events', {
                enabled: false
            });
            const draggedPageId = currentDragPageId;
            // Reset these as a safety measure at the end of any page drag
            setCurrentDragPageId(null);
            setIsShowingDropIndicator(false);

            const browser = getCurrentSync().Browser.wrapSync(currentOFIdentity);
            const isOnlyPage = pages.length === 1;
            const isReparenting = getDragState() === 'reparent';
            const isWithinTablist = isWithinParentBounds(event, containerRef.current?.getBoundingClientRect());
            const isReordering = getDragState() === 'reorder' && isWithinTablist;

            const draggedPage = await getPageWithLayout(draggedPageId);
            const draggedPageIndex = pages.findIndex((page) => page.pageId === draggedPage?.pageId);
            const isLayoutCreated = draggedPage?.isLayoutCreated;

            // Enterprise: Detect if page is creating or dropping into existing multi-view layout
            const isDraggingIntoLayout =
                event.dataTransfer.dropEffect === 'move' && event.dataTransfer.effectAllowed === 'linkMove';

            if (
                (workspaceWindowOptions.preventPageDragOut && !isOnlyPage) ||
                !draggedPageId ||
                isReparenting ||
                isReordering ||
                isDraggingIntoLayout
            ) {
                await updatePageForViewCountListener();

                // draggedPage may be null if page is already removed through layout override method
                if (!isLayoutCreated && !isReordering && draggedPage) {
                    await browser.removePage(draggedPage.pageId);
                }
                return;
            }

            // elementOffset is used to find the middle of the dragged page button
            const target = event.target as EventTarget & { offsetWidth?: number; offsetHeight: number };
            const elementOffsetX = target?.offsetWidth || 0;
            const elementOffsetY = target?.offsetHeight || 0;

            if (isOnlyPage) {
                // Edge case in window with only two page tabs
                // Don't move when dragging out inactive tab into another window's layout
                if (activePage.pageId === draggedPageId) {
                    // If it is the last page, rather than destroy and re-create a window - move it
                    const moveX = Math.floor(event.offsetX - elementOffsetX / 2);
                    const moveY = Math.floor(event.offsetY - elementOffsetY / 2);
                    (fin.me as OpenFin.Window).moveBy(moveX, moveY);
                }
            } else {
                const defaultTop = Math.floor(event.screenY - elementOffsetY / 2);
                const defaultLeft = Math.floor(event.screenX - elementOffsetX / 2);

                // If page we drag out is active, need to switch to another page to hide layout destruction from user
                if (draggedPage.isActive) {
                    const remainingPages = pages.filter((attachedPage) => attachedPage.pageId !== draggedPage.pageId);
                    const nextActivePage = getNextActivePageOnRemoval(draggedPageIndex, remainingPages);
                    await browser.setActivePage(nextActivePage.pageId);
                }

                await getCurrentSync().Browser.createWindow({
                    workspacePlatform: {
                        pages: [{ ...draggedPage, multiInstanceViewBehavior: 'reparent' } as ReparentAttachedPage],
                        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                        // @ts-ignore
                        windowType: 'enterprise'
                    },
                    defaultLeft,
                    defaultTop,
                    x: defaultLeft,
                    y: defaultTop,
                    reason: isLayoutCreated ? 'tearout' : undefined
                });
                if (!isLayoutCreated) {
                    await browser.removePage(draggedPage.pageId);
                }
            }
        },
        [
            activePage?.pageId,
            workspaceWindowOptions.preventPageDragOut,
            setIsShowingDropIndicator,
            updatePageForViewCountListener,
            currentDragPageId,
            pages
        ]
    );

    const isCloseHidden = workspaceWindowOptions.preventPageClose || workspaceWindowOptions.isLocked;

    const processedPages = useMemo(
        () => (isCloseHidden ? pages.map((page) => ({ ...page, closeButton: { hidden: true } })) : pages),
        [pages, isCloseHidden]
    );

    const contextGroups = useGetContextGroups();
    usePageIcon();

    return !workspaceWindowOptions.disableMultiplePages ? (
        <Container
            className={enterpriseStyles.tabsTopTab}
            ref={containerRef}
            onDrop={onDragDropHandler}
            onDragEnter={onDragEnterHandler}
            onDragLeave={onDragLeaveHandler}
            onDragOver={onDragOverHandler}
            isEnterprise={isEnterprise}
        >
            <ScreenReaderAnnouncement message={screenReaderAnnouncement} />

            <TabContainer
                className={enterpriseStyles.tabsContainer}
                ref={tabContainerRef}
                isEnterprise={isEnterprise}
                onWheel={handleTabContainerScroll}
                aria-label={t('aria.browserTabs')}
                role="tablist"
                data-testid={enterprisePageTestIds.tabContainer}
            >
                {shouldShowScrollShadows && <ScrollShadow shadowWidth="small" />}
                <WithDropIndicator
                    indicatorPosition={dropIndicatorPosition}
                    shouldShowIndicator={isShowingDropIndicator}
                >
                    {processedPages.map((page, index) => (
                        <PageButton
                            page={page}
                            key={page.pageId}
                            onPageClick={onPageClickHandler}
                            onPageDragStart={onPageDragStartHandler}
                            onPageDragEnd={onPageDragEndHandler}
                            onPageClose={requestClosePage}
                            dragDisabled={workspaceWindowOptions.isLocked || workspaceWindowOptions.preventPageDrag}
                            onPageDragOver={onPageDragOver}
                            isBeingReordered={currentDragPageId === page.pageId && pages.length > 1}
                            isDropRegion={isShowingDropIndicator && hoveredPageIndex === index}
                            colorChannel={
                                page.contextGroup && contextGroups.find((group) => group.id === page.contextGroup)
                            }
                        />
                    ))}
                </WithDropIndicator>
                {shouldShowScrollShadows && (
                    <ScrollShadow shadowWidth="small" offset={isNewTabButtonVisible ? SCROLL_SHADOW_OFFSET : 0} right />
                )}
            </TabContainer>
            {isNewTabButtonVisible && (
                <PlusButtonContainer className={enterpriseStyles.tabsAddButtonWrapper} windowFocused={windowFocused}>
                    <BaseButton
                        title={t('enterpriseContextMenu.newTab')}
                        onClick={onPlusClickHandler}
                        className={enterpriseStyles.tabsAddButton}
                        data-testid={enterprisePageTestIds.newPageButton}
                        width={24}
                        height={24}
                        isEnterprise={isEnterprise}
                    >
                        <Icon icon="PlusIcon" />
                    </BaseButton>
                </PlusButtonContainer>
            )}
        </Container>
    ) : (
        <Container isEnterprise={isEnterprise}>
            <TabContainer isEnterprise={isEnterprise}>
                <TextContainer isActive={false}>
                    <TextSpan>{singlePageWindowTabTitle}</TextSpan>
                </TextContainer>
            </TabContainer>
        </Container>
    );
};

const Container = forwardRef<
    HTMLDivElement,
    React.HTMLAttributes<HTMLDivElement> & {
        isEnterprise: boolean;
        ref?: React.MutableRefObject<HTMLDivElement>;
    }
>(({ isEnterprise: _isEnterprise, ...props }, ref) => {
    const Component = EnterpriseContainer;
    return <Component ref={ref} {...props} />;
});

Container.displayName = 'Container';

const BaseContainer = styled(Box)`
    -webkit-app-region: no-drag;
    user-select: auto;
    display: inline-flex;
    overflow: hidden;
    position: relative;

    .plusButton {
        flex-shrink: 0;
    }
`;

const EnterpriseContainer = styled(BaseContainer)`
    align-items: center;

    .plusButton {
        width: ${({ theme }) => theme.px.xxlarge};

        /// special casing?? yes or no ask product....
        height: 100%;
        margin-left: 0;
        padding-left: ${({ theme }) => theme.px.xsmall};

        &:hover {
            cursor: pointer;
            border-radius: ${({ theme }) => theme.px.xsmall};
        }
    }
`;

