import { useEffect } from 'react';

import type OpenFin from '@openfin/core';

import { createInlineDebugLogger } from '@common/utils/debug-log';
import { addLayoutEventListener, LayoutDOMEvent, removeLayoutEventListener } from '@common/utils/layout';
import { getCurrentOFWindow } from '@common/utils/window';

import { getLayoutContainerKeyForView } from '@enterprise/api/pages/getLayoutContainerKeyForView';

const debug = createInlineDebugLogger('useManagePageViewCount');

export type UpdatePageForViewCountForLayout = (layoutContainerKey?: string) => void | Promise<void>;

export const useManagePageViewCount = (
    updatePageForViewCountForLayout: UpdatePageForViewCountForLayout,
    activePageLayoutContainerKey: string | undefined
) => {
    useEffect(() => {
        const win = getCurrentOFWindow();

        const handleTabCreated = (ev: LayoutDOMEvent) => {
            if (ev.type !== 'tab-created') {
                return;
            }
            const layoutKey = ev.detail.originalElement.id;
            if (layoutKey) {
                void updatePageForViewCountForLayout(layoutKey);
            }
        };

        const handleViewAttachedOrDetached = async (e: { viewIdentity: OpenFin.Identity }) => {
            debug('handleViewAttachedOrDetached', { viewName: e.viewIdentity.name });
            try {
                // getLayoutContainerKeyForView calls view.getCurrentWindow() which can throw
                // if the view has already been destroyed (e.g. page removed during discard/save).
                // When layoutKey is undefined the view is gone or belongs to another window,
                // so there is no page to update.
                const layoutKey = await getLayoutContainerKeyForView(e.viewIdentity);
                if (!layoutKey) {
                    debug('no layout key resolved, skipping view count update', { viewName: e.viewIdentity.name });
                    return;
                }
                debug('resolved layoutKey', { layoutKey, viewName: e.viewIdentity.name });
                await updatePageForViewCountForLayout(layoutKey);
            } catch (err) {
                debug('view no longer available, skipping view count update', { viewName: e.viewIdentity.name });
            }
        };

        addLayoutEventListener('tab-created', handleTabCreated);
        win.addListener('view-attached', handleViewAttachedOrDetached);
        win.addListener('view-detached', handleViewAttachedOrDetached);

        return () => {
            win.removeListener('view-attached', handleViewAttachedOrDetached);
            win.removeListener('view-detached', handleViewAttachedOrDetached);
            removeLayoutEventListener('tab-created', handleTabCreated);
        };
    }, [updatePageForViewCountForLayout]);

    useEffect(() => {
        void updatePageForViewCountForLayout(undefined);
        // Run when the active page's layout key changes; undefined refreshes the active page in the callback.
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [activePageLayoutContainerKey]);
};
