import { useEffect, useRef } from 'react';

import styled from 'styled-components';

/**
 * Component that provides an aria-live region for accessibility announcements.
 * Updates the announcement text when it changes, ensuring screen readers announce
 * the new content even if the text is the same.
 *
 * @param announcementMessage - The message to announce. When null, no announcement is made.
 */
export const SearchAnnouncement: React.FC<{ announcementMessage: string | null }> = ({ announcementMessage }) => {
    const announcementRef = useRef<HTMLDivElement>(null);
    const previousAnnouncementRef = useRef<string | null>(null);

    // Update aria-live region only when announcementMessage actually changes
    useEffect(() => {
        if (announcementMessage !== previousAnnouncementRef.current && announcementRef.current) {
            // Clear the content first to force NVDA to re-read even if the text is the same
            announcementRef.current.textContent = '';
            // Use requestAnimationFrame to ensure the DOM updates before setting new content
            requestAnimationFrame(() => {
                if (announcementRef.current && announcementMessage) {
                    announcementRef.current.textContent = announcementMessage;
                }
            });
            previousAnnouncementRef.current = announcementMessage;
        }
    }, [announcementMessage]);

    return <Announcement ref={announcementRef} aria-live="assertive" aria-atomic="true" role="status" />;
};

const Announcement = styled.div`
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
`;
