import type OpenFin from '@openfin/core';

import { currentOFIdentity, WindowName } from './window';

export const getFindInPageViewIdentity = (browserIdentity?: OpenFin.Identity) => {
    return {
        uuid: (browserIdentity ?? currentOFIdentity).uuid,
        name: WindowName.FindInPageViewPrefix + (browserIdentity ?? currentOFIdentity).name
    };
};
