import { useCallback } from 'react';
import { useDispatch } from 'react-redux';

import { getLayoutConfig, mapContentComponentState } from '@common/utils/layout';

import { AttachedPageInternal, ReparentAttachedPage } from '@common/api/pages/shapes';

import { updatePageAtIndex } from '@enterprise/slices/pages/attached';

import { showHideTabsBasedOnViewCount } from '@enterprise/utils/layout';

import { resetLastFocusedView } from '@enterprise/hooks/EnterpriseSearchMenu/useUpdateViewExpansionState';

export const useOnLayoutCreated = () => {
    const dispatch = useDispatch();
    return useCallback(
        async (page: AttachedPageInternal, pageIndex: number) => {
            // It may be a reparent request, in which case we handle that logic and delete the extra data
            // thereafter returning the page to the AttachedPage type
            if ((page as ReparentAttachedPage).multiInstanceViewBehavior === 'reparent') {
                dispatch(
                    updatePageAtIndex({
                        index: pageIndex,
                        page: {
                            multiInstanceViewBehavior: undefined,
                            isLayoutCreated: true
                        } as Partial<AttachedPageInternal>
                    })
                );
            }

            const currentLayout = await getLayoutConfig(page.layoutContainerKey);

            const componentStates = currentLayout.content ? mapContentComponentState(currentLayout.content) : [];
            const viewCount = componentStates.length;

            if (viewCount > 1 && page.attachedPageType !== 'multiView') {
                dispatch(
                    updatePageAtIndex({
                        index: pageIndex,
                        page: {
                            attachedPageType: 'multiView',
                            singleViewName: undefined
                        }
                    })
                );
            } else if (viewCount === 1) {
                // For single-view pages, always ensure both attachedPageType and singleViewName are set
                const actualViewName = componentStates[0].name;
                dispatch(
                    updatePageAtIndex({
                        index: pageIndex,
                        page: {
                            attachedPageType: 'singleView',
                            singleViewName: actualViewName
                        }
                    })
                );
            }

            showHideTabsBasedOnViewCount(page, viewCount);

            // Ignore extraneous view-focused events before a layout is created.
            // Enables evaluating search input focus for views that get dragged out to create page level tabs.
            resetLastFocusedView();
        },
        [dispatch]
    );
};
