import { useCallback, useEffect, useMemo, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';

import type { Store } from '@reduxjs/toolkit';

import type OpenFin from '@openfin/core';

import debounce from 'lodash.debounce';

import { getFindInPageViewIdentity } from '@common/utils/get-browser-views';

import * as findInPageSlice from '@common/slices/find-in-page';

import { focusManager } from '@common/services/focus-manager';
import { FOCUS_PRIORITY } from '@common/types/focus';

import {
    closeFindInPageChannel,
    createFindInPageChannel,
    FindInPageChannelMessagePayload,
    sendFindInPageMessage
} from '../../utils/find-in-page/findInPageChannel';

const FIND_IN_PAGE_HOTKEY_DEBOUNCE_MS = 100;
const FIND_IN_PAGE_INPUT_DEBOUNCE_MS = 300;
const FIND_IN_PAGE_VIEW_WIDTH = 360;
const FIND_IN_PAGE_VIEW_HEIGHT = 50;
const FIND_IN_PAGE_VIEW_MARGIN = 12;

type Props = {
    selectActivePage: (state: any) => { pageId: string };
    selectSelectedViewsForPage: (state: any, pageId: string) => OpenFin.Identity[];
    store: Store;
};

/**
 * Hook for controlling find in page functionality from the browser window.
 *
 * @param selectActivePage - The selector for the active page.
 * @param selectSelectedViewsForPage - The selector for the selected views for the active page.
 * @param store - The Redux store.
 *
 * @returns Object containing functions to control find in page functionality from the browser window.
 */
export const useFindInPageBrowserWindow = ({ selectActivePage, selectSelectedViewsForPage, store }: Props) => {
    const dispatch = useDispatch();

    const activeContentViewFindInPageValue = useSelector(findInPageSlice.selectActiveContentViewFindInPageValue);
    const activeContentViewName = useSelector(findInPageSlice.selectActiveContentViewName);
    const findInPageIsVisibleForActiveContentView = useSelector(findInPageSlice.selectActiveContentViewVisibility);

    const channelRef = useRef<BroadcastChannel | null>(null);
    const isViewReady = useRef(false);
    const findTextUpdating = useRef(false);
    const isFindInPageViewVisible = useRef(false);

    /**
     * Clears the active content view which hides the find in page modal view.
     */
    const clearActiveContentView = useCallback((): void => {
        dispatch(findInPageSlice.setActiveContentViewName(null));
    }, [dispatch]);

    /**
     * Closes the channel used to communicate with the parent window
     */
    const closeChannel = useCallback(() => {
        if (!channelRef.current) {
            return;
        }
        closeFindInPageChannel(channelRef.current);
        channelRef.current = null;
    }, []);

    /**
     * Gets the content view that is currently in focus in the UI.
     */
    const getFocussedContentView = useCallback((): OpenFin.View | null => {
        const state = store.getState();
        const activePageId = selectActivePage(state).pageId;
        const contentViewIdentity = selectSelectedViewsForPage(state, activePageId)?.[0];
        if (!contentViewIdentity) {
            return null;
        }
        return fin.View.wrapSync(contentViewIdentity);
    }, [selectActivePage, selectSelectedViewsForPage, store]);

    /**
     * Gets the content view with the provided name or the current content view if no name is provided.
     *
     * @param contentViewName - The name of the content view to get. If not provided, the current content view is used.
     */
    const getContentView = useCallback(
        (contentViewName?: string): OpenFin.View | null => {
            let contentView: OpenFin.View | null = null;

            // If a view name is provided, return the view with that name
            if (contentViewName) {
                const contentViewIdentity = { uuid: fin.me.uuid, name: contentViewName };
                contentView = fin.View.wrapSync(contentViewIdentity);
            } else {
                // Otherwise, get the current content view
                contentView = getFocussedContentView();
            }

            if (!contentView) {
                console.warn('getContentView: no content view found', contentViewName);
                return null;
            }

            return contentView;
        },
        [getFocussedContentView]
    );

    /**
     * Clears up the content view state when the content view is closed.
     *
     * @param contentViewName - The name of the content view to clear the state of.
     */
    const contentViewClosed = useCallback(
        (contentViewName: string): void => {
            // Remove the content view state if it exists
            dispatch(findInPageSlice.deleteContentViewState(contentViewName));

            // If this is the active content view, update to the new active content view
            const currentActiveContentViewName = findInPageSlice.selectActiveContentViewName(store.getState());
            if (currentActiveContentViewName === contentViewName) {
                const newActiveContentView = getFocussedContentView();
                dispatch(
                    findInPageSlice.setActiveContentViewName(
                        newActiveContentView ? newActiveContentView.identity.name : null
                    )
                );
            }
        },
        [dispatch, getFocussedContentView, store]
    );

    /**
     * Sets the active content view to the provided content view.
     *
     * @param contentViewName - The name of the content view to set as the active content view.
     */
    const contentViewFocussed = useCallback(
        (contentViewName: string): void => {
            dispatch(findInPageSlice.setActiveContentViewName(contentViewName));
        },
        [dispatch]
    );

    /**
     * Executes a find in page search for the active content view.
     * This function updates the content view state with the find text value, the actual find is then triggered by `useEffect`.
     *
     * @param findText - The text to search for.
     */
    const executeFind = useCallback(
        (findText: string): void => {
            // Read the current value from Redux directly
            const currentActiveContentViewName = findInPageSlice.selectActiveContentViewName(store.getState());
            if (!currentActiveContentViewName) {
                return;
            }

            // Set the flag to indicate that the find text is currently being updated
            findTextUpdating.current = true;

            // Update the content view state with the search properties
            dispatch(
                findInPageSlice.updateContentViewState({
                    viewName: currentActiveContentViewName,
                    state: { value: findText }
                })
            );
        },
        [dispatch, store]
    );

    /**
     * Gets the find in page modal view.
     */
    const getFindInPageView = useCallback((): OpenFin.View => {
        const findInPageViewIdentity = getFindInPageViewIdentity();
        return fin.View.wrapSync(findInPageViewIdentity);
    }, []);

    /**
     * Hides the find in page modal for the active content view.
     * @param shouldRefocus - Whether to refocus the content view after hiding. Defaults to true.
     */
    const hide = useCallback(
        (shouldRefocus = true): void => {
            // Read the current value from Redux directly
            const currentActiveContentViewName = findInPageSlice.selectActiveContentViewName(store.getState());

            if (!currentActiveContentViewName) {
                return;
            }

            // Update the content view state to not visible
            dispatch(
                findInPageSlice.updateContentViewState({
                    viewName: currentActiveContentViewName,
                    state: { isVisible: false }
                })
            );

            // Mark that the modal was explicitly hidden
            isFindInPageViewVisible.current = false;

            // Focus the content view only if requested (avoid triggering view-focused events that might interfere with other UI)
            if (shouldRefocus) {
                const contentView = getContentView(currentActiveContentViewName);
                if (contentView) {
                    focusManager.requestFocus({
                        target: { type: 'view', identity: contentView.identity },
                        priority: FOCUS_PRIORITY.VIEW,
                        source: 'programmatic'
                    });
                }
            }
        },
        [dispatch, getContentView, store]
    );

    /**
     * Initializes the find in page modal view.
     */
    const initialize = useCallback(async (): Promise<void> => {
        try {
            // Attach the find in page view to the current window
            const findInPageView = getFindInPageView();
            await findInPageView.attach(fin.me.identity);
        } catch (error) {
            console.error('useFindInPageBrowserWindow: error initializing find in page view', error);
            return;
        }
    }, [getFindInPageView]);

    /**
     * Sends a message to the find-in-page modal view
     */
    const sendMessageToView = useCallback((message: FindInPageChannelMessagePayload) => {
        if (!channelRef.current) {
            console.warn('useFindInPageBrowserWindow: find in page channel not ready');
            return;
        }

        if (!isViewReady.current) {
            console.warn('useFindInPageBrowserWindow: find in page view not ready');
            return;
        }

        sendFindInPageMessage(channelRef.current, message);
    }, []);

    /**
     * Executes a find in page search and updates the Redux state with the results.
     *
     * @param contentView - The content view to execute the search on.
     * @param findValue - The text to search for. If `undefined` or an empty string, the search is cleared.
     * @param options - The find in page options.
     */
    const executeFindInPageAndUpdateState = useCallback(
        async (
            contentView: OpenFin.View,
            findValue: string | undefined,
            options: OpenFin.FindInPageOptions
        ): Promise<{ activeMatchOrdinal: number | null; matches: number | null }> => {
            let currentResultIndex: number | null = null;
            let totalResults: number | null = null;

            if (findValue) {
                // TODO: Update with proper OpenFin types once available (https://openfin.jira.com/browse/CORE-2366)
                const result = (await contentView.findInPage(findValue, options)) as unknown as {
                    activeMatchOrdinal: number;
                    matches: number;
                };
                currentResultIndex = result.activeMatchOrdinal;
                totalResults = result.matches;
            } else {
                // If find value is empty, clear the search
                contentView.stopFindInPage('clearSelection');
            }

            // Update the content view state with the updated counts
            dispatch(
                findInPageSlice.updateContentViewState({
                    viewName: contentView.identity.name,
                    state: {
                        currentResultIndex,
                        totalResults
                    }
                })
            );

            // Send the updated counts to the view
            sendMessageToView({
                type: 'update-state',
                currentResultIndex,
                totalResults
            });

            return { activeMatchOrdinal: currentResultIndex, matches: totalResults };
        },
        [dispatch, sendMessageToView]
    );

    /**
     * Applies the new find value to the active content view.
     * Executes the search and updates the result counts, or clears the search if no value is provided.
     *
     * @param findValue - The find text value from state.
     */
    const applyFindValueToContentView = useCallback(
        async (findValue: string | undefined): Promise<void> => {
            const currentState = store.getState();
            const currentActiveContentViewName = findInPageSlice.selectActiveContentViewName(currentState);
            if (!currentActiveContentViewName) {
                return;
            }

            const contentView = getContentView(currentActiveContentViewName);
            if (!contentView) {
                return;
            }

            // Skip if value unchanged AND not just updated by user
            const viewState = currentState.findInPage.contentViewStates[currentActiveContentViewName];
            if (viewState?.value === findValue && !findTextUpdating.current) {
                return;
            }
            findTextUpdating.current = false;

            // Execute the search and update results in state
            await executeFindInPageAndUpdateState(contentView, findValue, { findNext: true });
        },
        [executeFindInPageAndUpdateState, getContentView, store]
    );

    /**
     * Debounced version of `applyFindValueToContentView` to prevent excessive re-renders.
     */
    const debouncedApplyFindValueToContentView = useMemo(
        () =>
            debounce(applyFindValueToContentView, FIND_IN_PAGE_INPUT_DEBOUNCE_MS, {
                leading: false,
                trailing: true
            }),
        [applyFindValueToContentView]
    );

    /**
     * Navigates to the next result for the active content view.
     */
    const navigateToNextResult = useCallback(async (): Promise<void> => {
        const currentState = store.getState();
        const currentActiveContentViewName = findInPageSlice.selectActiveContentViewName(currentState);
        const currentFindInPageValue = findInPageSlice.selectActiveContentViewFindInPageValue(currentState);

        // Only operate on the active content view
        if (!currentActiveContentViewName) {
            return;
        }

        const contentView = getContentView(currentActiveContentViewName);
        if (!contentView) {
            return;
        }

        // If there is no find in page value, no need to navigate to next result
        if (!currentFindInPageValue) {
            return;
        }

        // Otherwise, navigate to the next result
        await executeFindInPageAndUpdateState(contentView, currentFindInPageValue, {
            findNext: false,
            forward: true
        });
    }, [executeFindInPageAndUpdateState, getContentView, store]);

    /**
     * Navigates to the previous result for the active content view.
     */
    const navigateToPreviousResult = useCallback(async (): Promise<void> => {
        const currentState = store.getState();
        const currentActiveContentViewName = findInPageSlice.selectActiveContentViewName(currentState);
        const currentFindInPageValue = findInPageSlice.selectActiveContentViewFindInPageValue(currentState);

        // Only operate on the active content view
        if (!currentActiveContentViewName) {
            return;
        }

        const contentView = getContentView(currentActiveContentViewName);
        if (!contentView) {
            return;
        }

        // If there is no find in page value, no need to navigate to previous result
        if (!currentFindInPageValue) {
            return;
        }

        // Otherwise, navigate to the previous result
        await executeFindInPageAndUpdateState(contentView, currentFindInPageValue, {
            findNext: false,
            forward: false
        });
    }, [executeFindInPageAndUpdateState, getContentView, store]);

    /**
     * Sets the bounds of the find in page modal view for the provided content view.
     *
     * @param contentView - The content view to set the bounds of the find in page modal view for.
     */
    const setFindInPageViewBounds = useCallback(
        async (contentView: OpenFin.View): Promise<void> => {
            const contentViewBounds = (await contentView.getBounds()) as OpenFin.WindowBounds;

            // If the view's right edge position is less than the modal width,
            // there isn't enough space to position from the right without bleeding off the left edge
            const modalWidthWithMargin = FIND_IN_PAGE_VIEW_WIDTH + FIND_IN_PAGE_VIEW_MARGIN;
            const notEnoughSpaceOnLeft = contentViewBounds.right < modalWidthWithMargin;

            // If the width of the content view is less than the width of the find in page view plus double margins,
            // we need to adjust the positioning
            const useReducedWidth = contentViewBounds.width < FIND_IN_PAGE_VIEW_WIDTH + FIND_IN_PAGE_VIEW_MARGIN * 2;

            let left: number;
            if (useReducedWidth && notEnoughSpaceOnLeft) {
                // If the view is narrow AND there's not enough space on the left, pin to the left
                // (can bleed over adjacent views to the right)
                left = contentViewBounds.left + FIND_IN_PAGE_VIEW_MARGIN;
            } else {
                // Normal case: position from the right
                left = contentViewBounds.right - (FIND_IN_PAGE_VIEW_WIDTH + FIND_IN_PAGE_VIEW_MARGIN);
            }

            const height = FIND_IN_PAGE_VIEW_HEIGHT;
            const top = contentViewBounds.top + FIND_IN_PAGE_VIEW_MARGIN;
            const width = FIND_IN_PAGE_VIEW_WIDTH;

            const findInPageView = getFindInPageView();
            await findInPageView.setBounds({ left, top, width, height });
        },
        [getFindInPageView]
    );

    /**
     * Refreshes the position of the find in page modal view if visible for the active content view.
     */
    const refresh = useCallback(async (): Promise<void> => {
        const currentState = store.getState();
        const currentActiveContentViewName = findInPageSlice.selectActiveContentViewName(currentState);
        const currentIsVisible = findInPageSlice.selectActiveContentViewVisibility(currentState);

        if (!currentActiveContentViewName || !currentIsVisible) {
            return;
        }

        const contentView = getContentView(currentActiveContentViewName);
        if (!contentView) {
            return;
        }
        await setFindInPageViewBounds(contentView);
    }, [getContentView, setFindInPageViewBounds, store]);

    /**
     * Shows the find in page modal for the specified content view.
     * Also sets that view as the active content view.
     *
     * @param contentViewName - The name of the content view to show the find in page modal for. If not provided, the current content view is used.
     */
    const show = useCallback(
        async (contentViewName?: string): Promise<void> => {
            const contentView = getContentView(contentViewName);
            if (!contentView) {
                return;
            }
            const { name: viewName } = contentView.identity;

            // Update the content view state to visible
            dispatch(
                findInPageSlice.updateContentViewState({
                    viewName,
                    state: { isVisible: true }
                })
            );

            // Set the content view as the active content view
            dispatch(findInPageSlice.setActiveContentViewName(viewName));

            // Execute search if there's existing text (user is reshowing modal)
            const viewState = store.getState().findInPage.contentViewStates[viewName];
            if (viewState?.value) {
                await executeFindInPageAndUpdateState(contentView, viewState.value, { findNext: true });
            }

            // Hide the search menu if it's open
            const browserIdentity = fin.me.identity;
            const searchMenuChannel = new BroadcastChannel(`search-menu-${browserIdentity.name}`);
            searchMenuChannel.postMessage({
                type: 'update-search-menu-state',
                shouldExpandMenu: { shouldExpand: false }
            });
            searchMenuChannel.close();

            // Send focus message to the view
            sendMessageToView({ type: 'focus-input' });
        },
        [dispatch, executeFindInPageAndUpdateState, getContentView, sendMessageToView, store]
    );

    /**
     * Debounced version of `show` to prevent excessive calls when hotkeys are pressed.
     */
    const debouncedShow = useMemo(
        () =>
            debounce(show, FIND_IN_PAGE_HOTKEY_DEBOUNCE_MS, {
                leading: true,
                trailing: false
            }),
        [show]
    );

    /**
     * Handles the view hotkey event for showing the find in page view.
     */
    const handleViewHotkeyEvent = useCallback(
        (e: OpenFin.Events.PlatformEvents.ByType<'view-hotkey'>) => {
            // Check if the hotkey event is for the current window
            const currentWindowIdentity = (fin.me as OpenFin.Window).identity;
            if (currentWindowIdentity.name !== e.target.name) {
                return;
            }

            if (e.command === 'findInPage.show') {
                debouncedShow();
            }
        },
        [debouncedShow]
    );

    /**
     * Handles the window hotkey event for showing the find in page view.
     */
    const handleWindowHotkeyEvent = useCallback(
        (e: OpenFin.Events.PlatformEvents.ByType<'window-hotkey'>) => {
            // Check if the hotkey event is for the current window
            const currentWindowIdentity = (fin.me as OpenFin.Window).identity;
            if (currentWindowIdentity.name !== e.name) {
                return;
            }

            if (e.command === 'findInPage.show') {
                debouncedShow();
            }
        },
        [debouncedShow]
    );

    /**
     * Handles messages received from the find-in-page modal view or other components.
     */
    const handleMessageFromView = useCallback(
        (ev: MessageEvent<FindInPageChannelMessagePayload>) => {
            const { data } = ev;
            switch (data.type) {
                case 'close':
                    hide();
                    break;

                case 'find-text-changed':
                    executeFind(data.value);
                    break;

                case 'next-result':
                    debouncedApplyFindValueToContentView.flush();
                    navigateToNextResult();
                    break;

                case 'previous-result':
                    debouncedApplyFindValueToContentView.flush();
                    navigateToPreviousResult();
                    break;

                case 'show':
                    show();
                    break;

                case 'hide-from-search-menu':
                    // Search menu is expanding, hide find-in-page without refocusing to avoid triggering view-focused event
                    hide(false);
                    break;

                case 'view-ready':
                    isViewReady.current = true;
                    break;
            }
        },
        [debouncedApplyFindValueToContentView, executeFind, hide, navigateToNextResult, navigateToPreviousResult, show]
    );

    /**
     * Handles the `view-url-changed` event for the current window.
     * When a view navigates, hides the find-in-page modal (matching Chrome behavior),
     * but retains the search text so it can be re-executed when the modal is shown again.
     */
    const handleViewUrlChanged = useCallback(
        async (e: OpenFin.Events.WindowEvents.ByType<'view-url-changed'>) => {
            const { viewIdentity } = e;
            const view = fin.View.wrapSync(viewIdentity);
            const viewState = store.getState().findInPage.contentViewStates[viewIdentity.name];

            // Only reset if there was an active find-in-page search for this view
            if (viewState?.value) {
                // Clear the search highlights in the view
                view.stopFindInPage('clearSelection');

                // Reset the find-in-page results for this view (keep value, clear result counts and hide modal)
                dispatch(
                    findInPageSlice.updateContentViewState({
                        viewName: viewIdentity.name,
                        state: {
                            currentResultIndex: null,
                            totalResults: null,
                            isVisible: false
                        }
                    })
                );
            }
        },
        [dispatch, store]
    );

    /**
     * Synchronizes the find in page view to the state of the provided content view.
     *
     * @param contentViewName - The name of the content view to synchronize the find in page view to.
     * @param isVisible - Whether the find in page view should be visible.
     */
    const syncFindInPageViewVisibilityToState = useCallback(
        async (contentViewName: string, isVisible: boolean): Promise<void> => {
            const findInPageView = getFindInPageView();

            // Hide the find in page view if no content view name is provided
            if (!contentViewName) {
                findInPageView.hide();
                isFindInPageViewVisible.current = false;
                return;
            }

            const contentView = getContentView(contentViewName);
            if (!contentView) {
                return;
            }

            if (isVisible) {
                // If the find in page view should be visible, first update the find in page view modal with existing find in page state for the content view
                findInPageView.hide();
                const viewState = store.getState().findInPage.contentViewStates[contentViewName];
                sendMessageToView({
                    type: 'update-state',
                    currentResultIndex: viewState?.currentResultIndex ?? null,
                    totalResults: viewState?.totalResults ?? null,
                    value: viewState?.value ?? null
                });

                // Then set the bounds of the find in page view and show it at the front
                await setFindInPageViewBounds(contentView);
                findInPageView.bringToFront();
                findInPageView.show();
                isFindInPageViewVisible.current = true;

                // Re-execute search if there are no current results (e.g., after navigation cleared them)
                const hasNoResults =
                    viewState?.currentResultIndex === null || viewState?.currentResultIndex === undefined;
                if (viewState?.value && hasNoResults) {
                    await executeFindInPageAndUpdateState(contentView, viewState.value, { findNext: true });
                }
            } else {
                // If the find in page view should be hidden, stop the find in page search and hide the find in page view
                contentView.stopFindInPage('clearSelection');
                findInPageView.hide();
                isFindInPageViewVisible.current = false;
            }
        },
        [
            executeFindInPageAndUpdateState,
            getContentView,
            getFindInPageView,
            sendMessageToView,
            setFindInPageViewBounds,
            store
        ]
    );

    useEffect(() => {
        if (!isViewReady.current) {
            return;
        }

        // Update the UI with state changes
        syncFindInPageViewVisibilityToState(activeContentViewName, findInPageIsVisibleForActiveContentView);
    }, [activeContentViewName, findInPageIsVisibleForActiveContentView, syncFindInPageViewVisibilityToState]);

    useEffect(() => {
        if (!isViewReady.current) {
            return;
        }

        // Update the UI with state changes
        debouncedApplyFindValueToContentView(activeContentViewFindInPageValue);

        return () => {
            debouncedApplyFindValueToContentView.cancel();
        };
    }, [activeContentViewFindInPageValue, debouncedApplyFindValueToContentView]);

    useEffect(() => {
        // Create channel with unique name based on window
        let cancelled = false;
        createFindInPageChannel().then((channel) => {
            if (cancelled) {
                return;
            }
            channelRef.current = channel;
            channelRef.current.onmessage = handleMessageFromView;
        });

        return () => {
            cancelled = true;
            closeChannel();
        };
    }, [closeChannel, handleMessageFromView, sendMessageToView]);

    useEffect(() => {
        // Clean up the debounced functions
        return () => {
            debouncedApplyFindValueToContentView.cancel();
            debouncedShow.cancel();
        };
    }, [debouncedApplyFindValueToContentView, debouncedShow]);

    useEffect(() => {
        // Register event listeners
        const platform = fin.Platform.getCurrentSync();
        platform.on('view-hotkey', handleViewHotkeyEvent);
        platform.on('window-hotkey', handleWindowHotkeyEvent);

        const win = fin.Window.getCurrentSync();
        win.addListener('view-url-changed', handleViewUrlChanged);

        return () => {
            platform.removeListener('view-hotkey', handleViewHotkeyEvent);
            platform.removeListener('window-hotkey', handleWindowHotkeyEvent);
            win.removeListener('view-url-changed', handleViewUrlChanged);
        };
    }, [handleViewHotkeyEvent, handleWindowHotkeyEvent, handleViewUrlChanged]);

    return useMemo(
        () => ({
            clearActiveContentView,
            contentViewClosed,
            contentViewFocussed,
            executeFind,
            hide,
            initialize,
            navigateToNextResult,
            navigateToPreviousResult,
            refresh,
            show
        }),
        [
            clearActiveContentView,
            contentViewClosed,
            contentViewFocussed,
            executeFind,
            hide,
            initialize,
            navigateToNextResult,
            navigateToPreviousResult,
            refresh,
            show
        ]
    );
};
